class Circle {
  #data;
  constructor(radius) {
    this.#data = Object.freeze({ radius });   // frozen holder
  }
  get radius() { return this.#data.radius; }
  get circumference() { return 2 * Math.PI * this.#data.radius; }
}

const data = new WeakMap();

class Circle {
  constructor(radius) {
    data.set(this, Object.freeze({ radius }));
  }
  get radius() { return data.get(this).radius; }
}

